const r = $input.first().json;
const http = Number(r.statusCode ?? 0);
const body = r.body ?? {};
const err = body.error ?? {};
// A 402 card error may carry the PaymentIntent under error.payment_intent.
const pi = body.id ?? body.error?.payment_intent?.id ?? null;
const st = body.status ?? null;

const out = (o) => [{ json: { ...o, stripe_pi_id: pi } }];

if (http === 200 && st === 'succeeded') {
  return out({ outcome: 'paid', httpStatus: 0, payment_error_code: null, payment_error_message: null });
}
if (http === 200 && st === 'processing') {
  return out({ outcome: 'pending', httpStatus: 202, payment_error_code: null, payment_error_message: null });
}
if (http === 200 && st === 'requires_action') {
  return out({ outcome: 'action_required', httpStatus: 402, payment_error_code: 'AUTHENTICATION_REQUIRED', payment_error_message: 'This card requires authentication and the customer is not present.' });
}
if (http === 200 && st === 'requires_capture') {
  return out({ outcome: 'error', httpStatus: 500, payment_error_code: 'CAPTURE_REQUIRED', payment_error_message: 'Payment authorized but not captured.' });
}
if (http === 402) {
  return out({ outcome: 'failed', httpStatus: 402, payment_error_code: err.code ?? 'card_declined', payment_error_message: err.message ?? 'Card declined', decline_code: err.decline_code ?? null });
}
if (http === 429 || http >= 500) {
  return out({ outcome: 'unknown', httpStatus: http === 429 ? 429 : 503, payment_error_code: err.code ?? `http_${http}`, payment_error_message: err.message ?? 'Payment provider unavailable' });
}
return out({ outcome: 'error', httpStatus: 500, payment_error_code: err.code ?? `http_${http}`, payment_error_message: err.message ?? 'Payment request failed' });
